const x=$json;
if(x.operation!=='create_cod_order') throw new Error('transaction_invalid_operation');
if(typeof x.customer_id!=='string'||!x.customer_id.trim()) throw new Error('transaction_missing_customer');
if(!['facebook','whatsapp','instagram','internal'].includes(x.channel))
 throw new Error('transaction_invalid_channel');
if(x.customer_confirmation!==true) throw new Error('transaction_confirmation_required');
if(typeof x.action_id!=='string'||!x.action_id.trim()||x.action_id.length>256)
 throw new Error('transaction_missing_action_id');
return [{json:{...x,store_id:x.store_id||'default'}}];

const x=$json;
// WF-10 must be the actual authorization boundary. This node fails closed
// if the upstream authorization result is explicitly absent/denied.
if(x.authorization_result!=='allow')
 throw new Error('transaction_not_authorized_by_wf10');
return [{json:{...x,authorization_asserted:true}}];

const req=$('Authorization Gate').first().json;
const row=$input.first()?.json||{};
if(row.action_id){
  return [{json:{
    idempotent_replay:true,customer_id:req.customer_id,action_id:req.action_id,
    existing_result:row.result_json||row.response_json||null,
    existing_status:row.status||null,
    operation:req.operation
  }}];
}
return [{json:{...req,idempotent_replay:false}}];

const req=$('Authorization Gate').first().json;
const pre=$input.first()?.json||{};
if(pre.success!==true || pre.verified!==true || pre.commerce_status!=='available')
 throw new Error('transaction_preflight_failed');
if(!pre.preflight) throw new Error('transaction_missing_preflight');

return [{json:{
 operation:'create_cod_order',
 customer_id:req.customer_id,channel:req.channel,store_id:req.store_id,
 action_id:req.action_id,
 customer_confirmation:true,
 payment_method:'cod',
 payment_status:'not_paid',
 preflight:pre.preflight,
 // Order creation must be bounded by WF-20; caller cannot provide
 // arbitrary endpoint, status, price or payment state.
 authorization_scope:'cod_order_create_only'
}}];

const req=$('Prepare COD Order Creation').first().json;
const r=$json;
if(r.commerce_status==='unavailable')
 throw new Error('commerce_unavailable_during_order_creation');

return [{json:{
 success:Boolean(r.success),
 customer_id:req.customer_id,channel:req.channel,store_id:req.store_id,
 action_id:req.action_id,commerce_status:r.commerce_status||'available',
 verified:Boolean(r.verified && r.success),
 order:r.order||null,error:r.error||null
}}];

const create=$('Normalize Order Creation').first().json;
const verify=$json;
if(create.success!==true || create.verified!==true) throw new Error('order_creation_not_verified');
if(verify.success!==true || verify.verified!==true) throw new Error('post_create_verification_failed');
const o=verify.order||create.order;
if(!o || o.id===undefined) throw new Error('missing_verified_order_id');
if(o.payment_method && o.payment_method!=='cod') throw new Error('unexpected_payment_method');
if(o.payment_status && o.payment_status!=='not_paid')
 throw new Error('cod_order_must_not_be_claimed_paid');

return [{json:{
 success:true,operation:'create_cod_order',customer_id:create.customer_id,
 channel:create.channel,action_id:create.action_id,
 commerce_status:'available',verified:true,
 order:{
   id:o.id,status:o.status||null,payment_method:'cod',
   payment_status:o.payment_status||'not_paid',
   total:o.total??null,currency:o.currency||null
 },
 message_state:'order_created_not_paid'
}}];
